import React, { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import * as THREE from "three";

const FRAGMENT_SHADER = `
uniform float iTime;
uniform vec2 iResolution;

float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

vec3 auroraGlow(vec2 p, float t) {
  vec3 glow = vec3(0.0);
  for (float i = 0.0; i < 5.0; i++) {
    vec2 q = p + vec2(
      sin(t * 0.11 + i * 1.9) * 0.55,
      cos(t * 0.09 + i * 2.4) * 0.35
    );
    float band = 0.07 / (abs(q.y + q.x * 0.35) + 0.18);
    band *= 0.5 + 0.5 * sin(t * 0.25 + i * 2.1);
    glow += vec3(0.08, 0.22, 0.55) * band;
  }
  return glow * 0.22;
}

float meteorStreak(vec2 uv, vec2 head, vec2 dir, float tailLen, float width) {
  vec2 rel = uv - head;
  float along = dot(rel, dir);
  float perp = abs(dot(rel, vec2(-dir.y, dir.x)));

  if (along > 0.012 || along < -tailLen) {
    return 0.0;
  }

  float tail = smoothstep(width * 6.0, width * 0.35, perp);
  tail *= smoothstep(-tailLen, 0.012, along);
  tail *= 1.0 + along / tailLen;

  float headGlow = smoothstep(0.014, 0.0, length(rel));
  headGlow *= step(along, 0.012);

  return tail * 0.85 + headGlow * 2.2;
}

void main() {
  vec2 uv = gl_FragCoord.xy / iResolution.xy;
  float aspect = iResolution.x / iResolution.y;
  vec2 p = (uv * 2.0 - 1.0) * vec2(aspect, 1.0);

  vec3 col = auroraGlow(p, iTime);

  for (float i = 0.0; i < 56.0; i++) {
    float id = i + 1.0;
    float s0 = hash11(id * 0.571);
    float s1 = hash11(id * 1.313);
    float s2 = hash11(id * 2.717);
    float s3 = hash11(id * 4.119);

    float speed = 0.22 + s0 * 0.28;
    float cycle = 4.5 + s1 * 5.5;
    float phase = s2 * cycle;
    float t = mod(iTime * speed + phase, cycle);

    vec2 dir = normalize(vec2(-0.78 - s0 * 0.18, -0.62 - s1 * 0.2));

    float spawnX = (s1 * 2.6 - 1.3) * aspect;
    float spawnY = 0.95 + s2 * 0.65;
    vec2 head = vec2(spawnX, spawnY) + dir * t * 1.45;

    float tailLen = 0.16 + s3 * 0.28;
    float width = 0.0014 + s0 * 0.0022;

    float m = meteorStreak(p, head, dir, tailLen, width);
    vec3 meteorColor = mix(
      vec3(0.12, 0.42, 0.95),
      vec3(0.82, 0.92, 1.0),
      s3
    );

    col += meteorColor * m * (0.45 + s2 * 0.55);
  }

  col = col / (col + vec3(0.85));
  gl_FragColor = vec4(col, 1.0);
}
`;

const VERTEX_SHADER = `
void main() {
  gl_Position = vec4(position, 1.0);
}
`;

/** 全屏 Three.js 流星 + 极光背景（固定层，不拦截点击） */
const AnimatedShaderBackground: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    if (prefersReducedMotion) return;

    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight, true);
    renderer.domElement.style.display = "block";
    container.appendChild(renderer.domElement);

    const material = new THREE.ShaderMaterial({
      uniforms: {
        iTime: { value: 0 },
        iResolution: {
          value: new THREE.Vector2(window.innerWidth, window.innerHeight)
        }
      },
      vertexShader: VERTEX_SHADER,
      fragmentShader: FRAGMENT_SHADER
    });

    const geometry = new THREE.PlaneGeometry(2, 2);
    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    let frameId = 0;
    let visible = document.visibilityState === "visible";

    const onVisibility = () => {
      visible = document.visibilityState === "visible";
    };
    document.addEventListener("visibilitychange", onVisibility);

    const animate = () => {
      frameId = requestAnimationFrame(animate);
      if (!visible) return;
      material.uniforms.iTime.value += 0.016;
      renderer.render(scene, camera);
    };
    animate();

    const handleResize = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      renderer.setSize(w, h, true);
      material.uniforms.iResolution.value.set(w, h);
    };
    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(frameId);
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("resize", handleResize);
      if (container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
      geometry.dispose();
      material.dispose();
      renderer.dispose();
    };
  }, []);

  return createPortal(
    <div ref={containerRef} className="animated-shader-bg" aria-hidden />,
    document.body
  );
};

export default AnimatedShaderBackground;

