import React, { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import * as THREE from "three";

const FRAGMENT_SHADER = `
uniform float iTime;
uniform vec2 iResolution;

#define NUM_OCTAVES 3

float rand(vec2 n) {
  return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 ip = floor(p);
  vec2 u = fract(p);
  u = u * u * (3.0 - 2.0 * u);

  float res = mix(
    mix(rand(ip), rand(ip + vec2(1.0, 0.0)), u.x),
    mix(rand(ip + vec2(0.0, 1.0)), rand(ip + vec2(1.0, 1.0)), u.x),
    u.y
  );
  return res * res;
}

float fbm(vec2 x) {
  float v = 0.0;
  float a = 0.3;
  vec2 shift = vec2(100.0);
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < NUM_OCTAVES; ++i) {
    v += a * noise(x);
    x = rot * x * 2.0 + shift;
    a *= 0.4;
  }
  return v;
}

vec4 auroraLayer(vec2 p, float timeShift) {
  float t = iTime + timeShift;
  vec2 v;
  vec4 o = vec4(0.0);
  float f = 2.0 + fbm(p + vec2(t * 5.0, 0.0)) * 0.5;

  for (float i = 0.0; i < 35.0; i++) {
    v =
      p +
      cos(i * i + (t + p.x * 0.08) * 0.025 + i * vec2(13.0, 11.0)) * 3.5 +
      vec2(sin(t * 3.0 + i) * 0.003, cos(t * 3.5 - i) * 0.003);
    float tailNoise = fbm(v + vec2(t * 0.5, i)) * 0.3 * (1.0 - (i / 35.0));
    vec4 auroraColors = vec4(
      0.1 + 0.3 * sin(i * 0.2 + t * 0.4),
      0.3 + 0.5 * cos(i * 0.3 + t * 0.5),
      0.7 + 0.3 * sin(i * 0.4 + t * 0.3),
      1.0
    );
    vec4 currentContribution =
      auroraColors *
      exp(sin(i * i + t * 0.8)) /
      length(max(v, vec2(v.x * f * 0.015, v.y * 1.5)));
    float thinnessFactor = smoothstep(0.0, 1.0, i / 35.0) * 0.6;
    o += currentContribution * (1.0 + tailNoise * 0.8) * thinnessFactor;
  }

  return o;
}

void main() {
  vec2 shake = vec2(sin(iTime * 1.2) * 0.005, cos(iTime * 2.1) * 0.005);
  vec2 p =
    ((gl_FragCoord.xy + shake * iResolution.xy) - iResolution.xy * 0.5) /
    iResolution.y *
    mat2(6.0, -4.0, 4.0, 6.0);

  p.x += iTime * 0.12;

  vec4 o =
    auroraLayer(p, 0.0) +
    auroraLayer(p + vec2(6.2, 0.35), 1.7) +
    auroraLayer(p + vec2(-6.2, -0.25), 3.4) +
    auroraLayer(p + vec2(12.4, 0.15), 5.1);

  o = tanh(pow(o / 100.0, vec4(1.6)));
  gl_FragColor = o * 1.5;
}
`;

const VERTEX_SHADER = `
void main() {
  gl_Position = vec4(position, 1.0);
}
`;

/** 全屏 Three.js 极光 shader 背景（固定层，不拦截点击） */
