input.contents:
/** 全屏正交四边形顶点 */
export const BACKDROP_VERTEX_SHADER = `
void main() {
  gl_Position = vec4(position, 1.0);
}
`;

/**
 * 极光层（原版算法，单实例居中采样）
 * 负责左下区域的柔长蓝青拖尾质感
 */
export const AURORA_LAYER_GLSL = `
#define AURORA_OCTAVES 3

float auroraRand(vec2 n) {
  return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}

float auroraNoise(vec2 p) {
  vec2 ip = floor(p);
  vec2 u = fract(p);
  u = u * u * (3.0 - 2.0 * u);
  float res = mix(
    mix(auroraRand(ip), auroraRand(ip + vec2(1.0, 0.0)), u.x),
    mix(auroraRand(ip + vec2(0.0, 1.0)), auroraRand(ip + vec2(1.0, 1.0)), u.x),
    u.y
  );
  return res * res;
}

float auroraFbm(vec2 x) {
  float v = 0.0;
  float a = 0.3;
  vec2 shift = vec2(100.0);
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < AURORA_OCTAVES; ++i) {
    v += a * auroraNoise(x);
    x = rot * x * 2.0 + shift;
    a *= 0.4;
  }
  return v;
}

vec3 sampleAurora(vec2 p, float timeShift) {
  float t = iTime + timeShift;
  vec2 v;
  vec4 o = vec4(0.0);
  float f = 2.0 + auroraFbm(p + vec2(t * 5.0, 0.0)) * 0.5;

  for (float i = 0.0; i < 35.0; i++) {
    v =
      p +
      cos(i * i + (t + p.x * 0.08) * 0.025 + i * vec2(13.0, 11.0)) * 3.5 +
      vec2(sin(t * 3.0 + i) * 0.003, cos(t * 3.5 - i) * 0.003);
    float tailNoise = auroraFbm(v + vec2(t * 0.5, i)) * 0.3 * (1.0 - (i / 35.0));
    vec4 auroraColors = vec4(
      0.1 + 0.3 * sin(i * 0.2 + t * 0.4),
      0.3 + 0.5 * cos(i * 0.3 + t * 0.5),
      0.7 + 0.3 * sin(i * 0.4 + t * 0.3),
      1.0
    );
    vec4 currentContribution =
      auroraColors *
      exp(sin(i * i + t * 0.8)) /
      length(max(v, vec2(v.x * f * 0.015, v.y * 1.5)));
    float thinnessFactor = smoothstep(0.0, 1.0, i / 35.0) * 0.6;
    o += currentContribution * (1.0 + tailNoise * 0.8) * thinnessFactor;
  }

  o = tanh(pow(o / 100.0, vec4(1.6)));
  return o.rgb * 1.5;
}
`;

/**
 * 流星层：屏幕 UV 全宽分布，统一斜向，循环动画（不整体漂移）
 */
export const METEOR_FIELD_GLSL = `
float meteorHash(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float meteorStreak(vec2 uv, vec2 head, vec2 dir, float tailLen, float width) {
  vec2 rel = uv - head;
  float along = dot(rel, dir);
  float perp = abs(dot(rel, vec2(-dir.y, dir.x)));

  if (along > 0.015 || along < -tailLen) {
    return 0.0;
  }

  float tail = smoothstep(width * 7.0, width * 0.4, perp);
  tail *= smoothstep(-tailLen, 0.015, along);
  tail *= 1.0 + along / tailLen;

  float headGlow = smoothstep(0.016, 0.0, length(rel));
  headGlow *= step(along, 0.015);

  return tail * 0.9 + headGlow * 2.4;
}

vec3 sampleMeteorField(vec2 p, float aspect) {
  vec3 sum = vec3(0.0);
  vec2 dir = normalize(vec2(0.74, -0.67));

  for (float i = 0.0; i < 52.0; i++) {
    float id = i + 1.0;
    float h0 = meteorHash(id * 0.571);
    float h1 = meteorHash(id * 1.313);
    float h2 = meteorHash(id * 2.717);
    float h3 = meteorHash(id * 4.119);

    float speed = 0.14 + h0 * 0.18;
    float cycle = 4.8 + h1 * 5.5;
    float phase = h2 * cycle;
    float t = mod(iTime * speed + phase, cycle);

    float lane = floor(h3 * 5.0);
    float spawnX = (h1 * 2.15 - 1.075) * aspect + (lane - 2.0) * aspect * 0.22;
    float spawnY = 0.82 + h2 * 0.58 + lane * 0.04;
    vec2 head = vec2(spawnX, spawnY) + dir * t * 0.62;

    float tailLen = 0.11 + h3 * 0.24;
    float width = 0.0011 + h0 * 0.0018;

    float m = meteorStreak(p, head, dir, tailLen, width);
    vec3 color = mix(
      vec3(0.1, 0.38, 0.92),
      vec3(0.78, 0.9, 1.0),
      h3
    );
    sum += color * m * (0.38 + h2 * 0.45);
  }

  return sum;
}
`;

/** 极光 + 流星 合成 */
export const METEOR_BACKDROP_FRAGMENT_SHADER = `
uniform float iTime;
uniform vec2 iResolution;

${AURORA_LAYER_GLSL}

${METEOR_FIELD_GLSL}

void main() {
  vec2 shake = vec2(sin(iTime * 1.2) * 0.005, cos(iTime * 2.1) * 0.005);
  vec2 p =
    ((gl_FragCoord.xy + shake * iResolution.xy) - iResolution.xy * 0.5) /
    iResolution.y *
    mat2(6.0, -4.0, 4.0, 6.0);

  float aspect = iResolution.x / iResolution.y;

  vec3 col = vec3(0.015, 0.02, 0.04);
  col += sampleAurora(p, 0.0) * 0.92;
  col += sampleMeteorField(p, aspect);

  col = col / (col + vec3(0.82));
  gl_FragColor = vec4(col, 1.0);
}
`;

import { useEffect } from "react";
import * as THREE from "three";

type UseGlslBackdropOptions = {
  containerRef: React.RefObject<HTMLDivElement | null>;
  fragmentShader: string;
  vertexShader: string;
};

/** 挂载全屏 GLSL 背景（固定层、随窗口缩放） */
export function useGlslBackdrop({
  containerRef,
  fragmentShader,
  vertexShader
}: UseGlslBackdropOptions): void {
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    if (prefersReducedMotion) return;

    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight, true);
    renderer.domElement.style.display = "block";
    container.appendChild(renderer.domElement);

    const material = new THREE.ShaderMaterial({
      uniforms: {
        iTime: { value: 0 },
        iResolution: {
          value: new THREE.Vector2(window.innerWidth, window.innerHeight)
        }
      },
      vertexShader,
      fragmentShader
    });

    const geometry = new THREE.PlaneGeometry(2, 2);
    scene.add(new THREE.Mesh(geometry, material));

    let frameId = 0;
    let visible = document.visibilityState === "visible";

    const onVisibility = () => {
      visible = document.visibilityState === "visible";
    };
    document.addEventListener("visibilitychange", onVisibility);

    const animate = () => {
      frameId = requestAnimationFrame(animate);
      if (!visible) return;
      material.uniforms.iTime.value += 0.016;
      renderer.render(scene, camera);
    };
    animate();

    const handleResize = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      renderer.setSize(w, h, true);
      material.uniforms.iResolution.value.set(w, h);
    };
    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(frameId);
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("resize", handleResize);
      if (container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
      geometry.dispose();
      material.dispose();
      renderer.dispose();
    };
  }, [containerRef, fragmentShader, vertexShader]);
}

import React, { useRef } from "react";
import { createPortal } from "react-dom";
import {
  BACKDROP_VERTEX_SHADER,
  METEOR_BACKDROP_FRAGMENT_SHADER
} from "./shaders";
import { useGlslBackdrop } from "./useGlslBackdrop";

/**
 * 暗色登录/全站背景：极光质感 + 全屏流星层（独立模块）
 */
const MeteorBackground: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useGlslBackdrop({
    containerRef,
    vertexShader: BACKDROP_VERTEX_SHADER,
    fragmentShader: METEOR_BACKDROP_FRAGMENT_SHADER
  });

  return createPortal(
    <div ref={containerRef} className="meteor-backdrop" aria-hidden />,
    document.body
  );
};

export default MeteorBackground;

import React from "react";
import MeteorBackground from "./meteor/MeteorBackground";
import { useThemeMode } from "../state/ThemeContext";

/** 暗色主题下全站流星 + 极光背景 */
const AppShaderBackdrop: React.FC = () => {
  const { effectiveTheme } = useThemeMode();
  if (effectiveTheme !== "dark") return null;
  return <MeteorBackground />;
};

export default AppShaderBackdrop;

