import React, { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import * as THREE from "three";

/**
 * 根因：原版 aurora 使用 length(max(v, vec2(v.x*f*0.015, v.y*1.5)))，
 * 仅在 v.x 为负时衰减慢 → 亮带只占屏宽约一半，与 canvas/CSS 无关。
 * 修复：在 shader 空间按 period 横向平铺 auroraPass，用 max 合成（不溢色）。
 * 流星：独立 meteorField 层，全宽泳道分布。
 */
const FRAGMENT_SHADER = `
uniform float iTime;
uniform vec2 iResolution;

#define NUM_OCTAVES 3
#define AURORA_TILES 6

float rand(vec2 n) {
  return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 ip = floor(p);
  vec2 u = fract(p);
  u = u * u * (3.0 - 2.0 * u);

  float res = mix(
    mix(rand(ip), rand(ip + vec2(1.0, 0.0)), u.x),
    mix(rand(ip + vec2(0.0, 1.0)), rand(ip + vec2(1.0, 1.0)), u.x),
    u.y
  );
  return res * res;
}

float fbm(vec2 x) {
  float v = 0.0;
  float a = 0.3;
  vec2 shift = vec2(100.0);
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < NUM_OCTAVES; ++i) {
    v += a * noise(x);
    x = rot * x * 2.0 + shift;
    a *= 0.4;
  }
  return v;
}

vec4 auroraPass(vec2 p, float timeShift) {
  float t = iTime + timeShift;
  vec2 v;
  vec4 o = vec4(0.0);
  float f = 2.0 + fbm(p + vec2(t * 5.0, 0.0)) * 0.5;

  for (float i = 0.0; i < 35.0; i++) {
    v =
      p +
      cos(i * i + (t + p.x * 0.08) * 0.025 + i * vec2(13.0, 11.0)) * 3.5 +
      vec2(sin(t * 3.0 + i) * 0.003, cos(t * 3.5 - i) * 0.003);
    float tailNoise = fbm(v + vec2(t * 0.5, i)) * 0.3 * (1.0 - (i / 35.0));
    vec4 auroraColors = vec4(
      0.1 + 0.3 * sin(i * 0.2 + t * 0.4),
      0.3 + 0.5 * cos(i * 0.3 + t * 0.5),
      0.7 + 0.3 * sin(i * 0.4 + t * 0.3),
      1.0
    );
    vec4 currentContribution =
      auroraColors *
      exp(sin(i * i + t * 0.8)) /
      length(max(v, vec2(v.x * f * 0.015, v.y * 1.5)));
    float thinnessFactor = smoothstep(0.0, 1.0, i / 35.0) * 0.6;
    o += currentContribution * (1.0 + tailNoise * 0.8) * thinnessFactor;
  }

  return o;
}

vec4 auroraFullScreen(vec2 p, float aspect) {
  float period = aspect * 0.78 + 0.55;
  vec4 best = vec4(0.0);

  for (float k = 0.0; k < float(AURORA_TILES); k++) {
    vec2 offset = vec2(period * k, 0.06 * k - 0.08);
    best = max(best, auroraPass(p - offset, k * 1.55));
  }

  best = max(best, auroraPass(p - vec2(period * 2.4, -0.28), 7.2));
  return best;
}

float meteorHash(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

float meteorStreak(vec2 uv, vec2 head, vec2 dir, float tailLen, float width) {
  vec2 rel = uv - head;
  float along = dot(rel, dir);
  float perp = abs(dot(rel, vec2(-dir.y, dir.x)));

  if (along > 0.012 || along < -tailLen) {
    return 0.0;
  }

  float tail = smoothstep(width * 4.5, width * 0.25, perp);
  tail *= smoothstep(-tailLen, 0.012, along);
  tail *= 1.0 + 0.85 * (along / tailLen);

  float headGlow = smoothstep(0.012, 0.0, length(rel));
  headGlow *= step(along, 0.012);

  return tail + headGlow * 2.6;
}

vec3 meteorField(vec2 p, float aspect) {
  vec3 sum = vec3(0.0);
  vec2 dir = normalize(vec2(0.74, -0.67));

  for (float i = 0.0; i < 56.0; i++) {
    float id = i + 1.0;
    float h0 = meteorHash(id * 0.571);
    float h1 = meteorHash(id * 1.313);
    float h2 = meteorHash(id * 2.717);
    float h3 = meteorHash(id * 4.119);

    float speed = 0.14 + h0 * 0.18;
    float cycle = 4.8 + h1 * 5.5;
    float phase = h2 * cycle;
    float t = mod(iTime * speed + phase, cycle);

    float lane = floor(h3 * 8.0);
    float spawnX = (h1 * 2.35 - 1.175) * aspect + (lane - 3.5) * aspect * 0.17;
    float spawnY = 0.78 + h2 * 0.62 + lane * 0.03;
    vec2 head = vec2(spawnX, spawnY) + dir * t * 0.62;

    float tailLen = 0.1 + h3 * 0.22;
    float width = 0.0009 + h0 * 0.0015;

    float m = meteorStreak(p, head, dir, tailLen, width);
    vec3 color = mix(vec3(0.12, 0.42, 0.95), vec3(0.85, 0.94, 1.0), h3);
    sum += color * m * (0.4 + h2 * 0.48);
  }

  return sum;
}

void main() {
  vec2 shake = vec2(sin(iTime * 1.2) * 0.005, cos(iTime * 2.1) * 0.005);
  vec2 p =
    ((gl_FragCoord.xy + shake * iResolution.xy) - iResolution.xy * 0.5) /
    iResolution.y *
    mat2(6.0, -4.0, 4.0, 6.0);

  float aspect = iResolution.x / iResolution.y;

  vec4 auroraRaw = auroraFullScreen(p, aspect);
  vec3 col = tanh(pow(auroraRaw / 100.0, vec4(1.6))).rgb * 1.5;
  col += meteorField(p, aspect) * 0.52;

  col = col / (col + vec3(0.72));
  gl_FragColor = vec4(col, 1.0);
}
`;

const VERTEX_SHADER = `
void main() {
  gl_Position = vec4(position, 1.0);
}
`;

const AnimatedShaderBackground: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    if (prefersReducedMotion) return;

    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    const canvas = renderer.domElement;
    canvas.style.display = "block";
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    container.appendChild(canvas);

    const material = new THREE.ShaderMaterial({
      uniforms: {
        iTime: { value: 0 },
        iResolution: { value: new THREE.Vector2(1, 1) }
      },
      vertexShader: VERTEX_SHADER,
      fragmentShader: FRAGMENT_SHADER
    });

    const geometry = new THREE.PlaneGeometry(2, 2);
    scene.add(new THREE.Mesh(geometry, material));

    const syncSize = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      renderer.setSize(w, h, false);
      material.uniforms.iResolution.value.set(w, h);
    };

    syncSize();

    let frameId = 0;
    let visible = document.visibilityState === "visible";

    const onVisibility = () => {
      visible = document.visibilityState === "visible";
    };
    document.addEventListener("visibilitychange", onVisibility);

    const animate = () => {
      frameId = requestAnimationFrame(animate);
      if (!visible) return;
      material.uniforms.iTime.value += 0.016;
      renderer.render(scene, camera);
    };
    animate();

    const ro = new ResizeObserver(syncSize);
    ro.observe(container);
    window.addEventListener("resize", syncSize);

    return () => {
      cancelAnimationFrame(frameId);
      ro.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("resize", syncSize);
      if (container.contains(canvas)) {
        container.removeChild(canvas);
      }
      geometry.dispose();
      material.dispose();
      renderer.dispose();
    };
  }, []);

  return createPortal(
    <div ref={containerRef} className="animated-shader-backdrop" aria-hidden />,
    document.body
  );
};

export default AnimatedShaderBackground;

