#!/usr/bin/env python3
"""Generate minimal black line tab bar icons (81x81) for WeChat mini program."""
from pathlib import Path

try:
    from PIL import Image, ImageDraw
except ImportError:
    raise SystemExit("pip install pillow")

ROOT = Path(__file__).resolve().parent.parent / "static" / "tab"
ROOT.mkdir(parents=True, exist_ok=True)

GRAY = (100, 116, 139, 255)
BLUE = (37, 99, 235, 255)
W, H = 81, 81


def blank():
    return Image.new("RGBA", (W, H), (255, 255, 255, 0))


def save_pair(name, draw_fn):
    for active, color in ((False, GRAY), (True, BLUE)):
        img = blank()
        d = ImageDraw.Draw(img)
        draw_fn(d, color)
        suffix = "-active" if active else ""
        img.save(ROOT / f"{name}{suffix}.png")


def draw_home(d, c):
    d.line([(20, 38), (40, 20), (60, 38)], fill=c, width=3)
    d.rectangle([26, 38, 54, 62], outline=c, width=3)


def draw_market(d, c):
    for i, x in enumerate((18, 36, 54)):
        d.rectangle([x, 22 + i * 4, x + 14, 58 - i * 2], outline=c, width=3)


def draw_chat(d, c):
    d.rounded_rectangle([16, 20, 64, 52], radius=8, outline=c, width=3)
    d.polygon([(28, 52), (36, 64), (38, 52)], outline=c, fill=c)


def draw_mine(d, c):
    d.ellipse([30, 18, 50, 38], outline=c, width=3)
    d.arc([22, 36, 58, 68], start=200, end=340, fill=c, width=3)


save_pair("home", draw_home)
save_pair("market", draw_market)
save_pair("chat", draw_chat)
save_pair("mine", draw_mine)
print("written to", ROOT)

