"""扫码看广 · 独立后端（与 downAiGC 无关）"""
from __future__ import annotations

import json
import os
import urllib.error
import urllib.parse
import urllib.request
from datetime import timedelta
from pathlib import Path
from typing import Any, Dict

from dotenv import load_dotenv
from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.security import OAuth2PasswordBearer
from fastapi.staticfiles import StaticFiles
from jose import JWTError, jwt
from pydantic import BaseModel, Field
from sqlalchemy.orm import Session

load_dotenv(Path(__file__).resolve().parent / ".env")

from db import Base, SessionLocal, engine, get_db
import models  # noqa: F401
import repo

JWT_ALG = "HS256"
oauth2 = OAuth2PasswordBearer(tokenUrl="/api/adhub/auth/weixin")


def _jwt_secret() -> str:
    return os.getenv("JWT_SECRET_KEY", "scan-ad-dev-secret").strip() or "scan-ad-dev-secret"


def _public_base() -> str:
    return (os.getenv("PUBLIC_BASE") or "http://127.0.0.1:8001").rstrip("/")


def _wechat_appid() -> str:
    return (os.getenv("WECHAT_MP_APPID") or "").strip()


def _wechat_secret() -> str:
    return (os.getenv("WECHAT_MP_SECRET") or "").strip()


def _dev_login() -> bool:
    return (os.getenv("DEV_LOGIN") or "1").strip().lower() in ("1", "true", "yes")


def create_token(account_id: str) -> str:
    from datetime import datetime, timezone

    now = datetime.now(timezone.utc)
    exp = now + timedelta(days=30)
    payload = {"sub": account_id, "typ": "scan-ad", "iat": int(now.timestamp()), "exp": int(exp.timestamp())}
    return jwt.encode(payload, _jwt_secret(), algorithm=JWT_ALG)


async def current_account(token: str = Depends(oauth2), db: Session = Depends(get_db)) -> Dict[str, Any]:
    try:
        payload = jwt.decode(token, _jwt_secret(), algorithms=[JWT_ALG])
        if payload.get("typ") != "scan-ad":
            raise HTTPException(status_code=401, detail="Invalid token")
        account_id = payload.get("sub")
        if not account_id:
            raise HTTPException(status_code=401, detail="Invalid token")
    except JWTError:
        raise HTTPException(status_code=401, detail="Invalid token")
    acc = repo.get_account(db, str(account_id))
    if not acc:
        raise HTTPException(status_code=401, detail="Account not found")
    return {"id": acc.id, "account": acc}


def _exchange_weixin_code(code: str) -> tuple[str, str | None]:
    import hashlib

    code = (code or "").strip()
    if not code:
        raise HTTPException(status_code=400, detail="缺少微信 code")
    appid, secret = _wechat_appid(), _wechat_secret()
    if _dev_login() or (not appid and not secret):
        digest = hashlib.sha256(code.encode("utf-8")).hexdigest()[:24]
        return f"dev_openid_{digest}", None
    if not appid or not secret:
        raise HTTPException(
            status_code=503,
            detail="请在本项目 server/.env 配置 WECHAT_MP_APPID / WECHAT_MP_SECRET",
        )
    qs = urllib.parse.urlencode(
        {"appid": appid, "secret": secret, "js_code": code, "grant_type": "authorization_code"}
    )
    url = f"https://api.weixin.qq.com/sns/jscode2session?{qs}"
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            data = json.loads(resp.read().decode("utf-8"))
    except urllib.error.URLError as exc:
        raise HTTPException(status_code=502, detail="微信服务暂不可用") from exc
    if data.get("errcode"):
        raise HTTPException(status_code=400, detail=f"微信登录失败: {data.get('errmsg', data.get('errcode'))}")
    openid = data.get("openid")
    if not openid:
        raise HTTPException(status_code=400, detail="微信登录失败: 无 openid")
    return str(openid), data.get("unionid")


class WeixinLoginRequest(BaseModel):
    code: str
    nickname: str = ""
    avatarUrl: str = ""


class RealnameRequest(BaseModel):
    realName: str = Field(min_length=2, max_length=32)
    idNumber: str = Field(min_length=15, max_length=20)


class PublisherContactRequest(BaseModel):
    contactPhone: str = ""
    contactEmail: str = ""
    websiteUrl: str = ""
    bio: str = ""


class AdvertiserRegisterRequest(BaseModel):
    companyName: str = Field(min_length=2, max_length=128)
    contactName: str = ""
    contactPhone: str = ""
    contactEmail: str = ""
    bio: str = ""


class CooperationRequest(BaseModel):
    toAccountId: str
    message: str = ""


class ChatSendRequest(BaseModel):
    content: str = Field(min_length=1, max_length=2000)


class WatchCompleteRequest(BaseModel):
    code: str
    viewerKey: str = ""
    durationSec: int = Field(ge=0, le=600)


app = FastAPI(title="扫码看广 API")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["*"],
    allow_headers=["*"],
)

_static = Path(__file__).resolve().parent / "static"
if _static.is_dir():
    app.mount("/static", StaticFiles(directory=str(_static)), name="static")


@app.on_event("startup")
def _startup() -> None:
    Base.metadata.create_all(bind=engine)


@app.get("/api/health")
def health() -> Dict[str, str]:
    return {"status": "ok", "service": "scan-ad"}


@app.post("/api/adhub/auth/weixin")
def weixin_login(req: WeixinLoginRequest, db: Session = Depends(get_db)) -> Dict[str, Any]:
    openid, unionid = _exchange_weixin_code(req.code)
    acc = repo.upsert_weixin_account(
        db, openid=openid, unionid=unionid, nickname=req.nickname.strip(), avatar_url=req.avatarUrl.strip()
    )
    return {"accessToken": create_token(acc.id), "account": repo.account_me_dict(db, acc)}


@app.get("/api/adhub/me")
def me(ctx: Dict[str, Any] = Depends(current_account), db: Session = Depends(get_db)) -> Dict[str, Any]:
    db.refresh(ctx["account"])
    return repo.account_me_dict(db, ctx["account"])


@app.put("/api/adhub/me/publisher")
def update_publisher(
    req: PublisherContactRequest, ctx: Dict[str, Any] = Depends(current_account), db: Session = Depends(get_db)
) -> Dict[str, Any]:
    repo.update_publisher_contact(
        db, ctx["account"], contact_phone=req.contactPhone, contact_email=req.contactEmail,
        website_url=req.websiteUrl, bio=req.bio,
    )
    db.refresh(ctx["account"])
    return repo.account_me_dict(db, ctx["account"])


@app.post("/api/adhub/me/verify-realname")
def verify_realname(
    req: RealnameRequest, ctx: Dict[str, Any] = Depends(current_account), db: Session = Depends(get_db)
) -> Dict[str, Any]:
    try:
        repo.submit_realname(db, ctx["account"], real_name=req.realName, id_number=req.idNumber)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    db.refresh(ctx["account"])
    return repo.account_me_dict(db, ctx["account"])


@app.get("/api/adhub/me/qr")
def my_qr(ctx: Dict[str, Any] = Depends(current_account), db: Session = Depends(get_db)) -> Dict[str, Any]:
    acc = ctx["account"]
