def record_watch_complete(
    db: Session,
    *,
    qr_code: str,
    viewer_key: str,
    ip_address: str,
    duration_sec: int,
    campaign_id: str | None = None,
) -> tuple[bool, str, dict]:
    slot = get_qr_by_code(db, qr_code)
    if not slot:
        return False, "invalid_code", {}
    publisher_id = slot.account_id
    prof = db.get(AdHubPublisherProfile, publisher_id)
    if not prof or prof.verify_status != "verified":
        return False, "publisher_not_verified", {}

    campaign: AdHubCampaign | None = None
    if campaign_id:
        campaign = db.get(AdHubCampaign, campaign_id)
    if not campaign:
        link = db.scalar(
            select(AdHubQrCampaignLink)
            .where(AdHubQrCampaignLink.qr_code == qr_code, AdHubQrCampaignLink.active.is_(True))
            .order_by(AdHubQrCampaignLink.created_at.desc())
            .limit(1)
        )
        if link:
            campaign = db.get(AdHubCampaign, link.campaign_id)

    min_duration = max(25, int(campaign.duration_sec) - 5) if campaign else 25
    reward_points = int(campaign.publisher_reward_points) if campaign and not False else 0

    suspicious = False
    if duration_sec < min_duration:
        suspicious = True
    since = _now() - timedelta(hours=1)
    recent_same_viewer = int(
        db.scalar(
            select(func.count(AdHubWatchEvent.id)).where(
                AdHubWatchEvent.qr_code == qr_code,
                AdHubWatchEvent.viewer_key == viewer_key,
                AdHubWatchEvent.completed.is_(True),
                AdHubWatchEvent.created_at >= since,
            )
        )
        or 0
    )
    if recent_same_viewer >= 5:
        suspicious = True

    if campaign and not suspicious:
        reward_points = int(campaign.publisher_reward_points)
    elif suspicious:
        reward_points = 0

    evt = AdHubWatchEvent(
        qr_code=qr_code,
        publisher_account_id=publisher_id,
        campaign_id=campaign.id if campaign else None,
        viewer_key=viewer_key,
        ip_address=ip_address or "",
        duration_sec=duration_sec,
        completed=True,
        suspicious=suspicious,
        publisher_reward_points=reward_points if not suspicious else 0,
    )
    db.add(evt)

    if campaign:
        campaign.views_total = int(campaign.views_total) + 1
        if suspicious:
            campaign.views_suspicious = int(campaign.views_suspicious) + 1
        else:
            campaign.views_valid = int(campaign.views_valid) + 1

    if suspicious:
        prof.fraud_flags = int(prof.fraud_flags) + 1
        score = _adjust_reputation(db, publisher_id, -8, "疑似刷量观看")
    else:
        score = _adjust_reputation(db, publisher_id, +1, "正常完成观看")

    db.commit()
    return True, "ok" if not suspicious else "suspicious", {
        "publisherReputation": score,
        "suspicious": suspicious,
        "publisherRewardPoints": reward_points if not suspicious else 0,
        "campaignId": campaign.id if campaign else None,
        "campaignTitle": campaign.title if campaign else None,
    }

