def _migrate_campaign_schema() -> None:
    from sqlalchemy import text

    with engine.begin() as conn:
        cols = conn.execute(text("PRAGMA table_info(adhub_watch_events)")).fetchall()
        col_names = {row[1] for row in cols} if cols else set()
        if "campaign_id" not in col_names:
            conn.execute(text("ALTER TABLE adhub_watch_events ADD COLUMN campaign_id VARCHAR(36)"))
        if "publisher_reward_points" not in col_names:
            conn.execute(text("ALTER TABLE adhub_watch_events ADD COLUMN publisher_reward_points INTEGER DEFAULT 0"))

