/** 信誉分展示：当前值/100 */
export function formatReputation(score) {
  const n = Number(score);
  const s = Number.isFinite(n) ? Math.max(0, Math.min(100, Math.round(n))) : 100;
  return `${s}/100`;
}

/** 人民币展示（单价或金额） */
export function formatYuan(yuan) {
  const n = Number(yuan);
  if (!Number.isFinite(n)) return "¥0.00";
  return `¥${n.toFixed(2)}`;
}

