import { apiRequest } from "./api.js";

let meCache = { data: null, ts: 0 };
const ME_TTL_MS = 10000;

export function fetchMeCached(force = false) {
  const now = Date.now();
  if (!force && meCache.data && now - meCache.ts < ME_TTL_MS) {
    return Promise.resolve(meCache.data);
  }
  return apiRequest("/api/adhub/me").then((d) => {
    meCache.data = d;
    meCache.ts = Date.now();
    return d;
  });
}

export function clearMeCache() {
  meCache = { data: null, ts: 0 };
}

let throttleMap = {};

export function throttled(key, fn, intervalMs = 8000) {
  const now = Date.now();
  const last = throttleMap[key] || 0;
  if (now - last < intervalMs) {
    return Promise.resolve(null);
  }
  throttleMap[key] = now;
  return fn();
}

export function resetThrottle(key) {
  delete throttleMap[key];
}

