const KEY = "adhub_home_role";

export function getHomeRole() {
  const v = uni.getStorageSync(KEY);
  return v === "advertiser" ? "advertiser" : "publisher";
}

export function setHomeRole(role) {
  uni.setStorageSync(KEY, role === "advertiser" ? "advertiser" : "publisher");
}

export const VALID_MODES = [
  { value: "time_ratio", label: "有效时长/总时长" },
  { value: "click_jump", label: "点击跳转即有效" },
  { value: "browse_sec", label: "跳转后浏览/操作时长" },
  { value: "complete_and_click", label: "看完并点击跳转" },
  { value: "complete_click_browse", label: "看完+点击+浏览时长" }
];

export const SHAKE_MODES = [
  { value: "off", label: "关闭摇一摇" },
  { value: "advertiser", label: "广告商直接开启" },
  { value: "publisher_apply", label: "流量主申请后启用" }
];

export function validModeLabel(mode) {
  const row = VALID_MODES.find((m) => m.value === mode);
  return row ? row.label : "有效时长/总时长";
}

export function formatValidRule(c) {
  if (!c) return "-";
  const total = c.durationSec || 30;
  const valid = c.validDurationSec != null ? c.validDurationSec : Math.max(1, total - 5);
  const browse = c.validBrowseSec || 0;
  switch (c.validMode || "time_ratio") {
    case "click_jump":
      return "点击广告跳转即有效";
    case "browse_sec":
      return `跳转后浏览/操作 ${browse || 3} 秒有效`;
    case "complete_and_click":
      return `看完 ${total} 秒并点击跳转`;
    case "complete_click_browse":
      return `看完 ${total} 秒 + 点击 + 浏览 ${browse || 3} 秒`;
    default:
      return `有效 ${valid} 秒 / 总时长 ${total} 秒`;
  }
}

export function shakeModeLabel(mode) {
  const row = SHAKE_MODES.find((m) => m.value === mode);
  return row ? row.label : "关闭";
}

