@app.get("/api/adhub/advertiser/campaigns/{campaign_id}/stats")
def campaign_stats(campaign_id: str, ctx: Dict = Depends(current_account), db: Session = Depends(get_db)):
    row = repo.get_campaign_stats(db, campaign_id, ctx["id"])
    if not row:
        raise HTTPException(status_code=404, detail="Not found")
    return row


@app.post("/api/adhub/advertiser/campaigns/upload-media")
async def campaign_upload_media(
    file: UploadFile = File(...),
    ctx: Dict = Depends(current_account),
):
    if not ctx["account"].is_advertiser:
        raise HTTPException(status_code=403, detail="not_advertiser")
    ct = (file.content_type or "").lower()
    if not (ct.startswith("image/") or ct.startswith("video/")):
        raise HTTPException(status_code=400, detail="请上传图片或视频")
    raw = await file.read()
    if len(raw) > 20 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="文件不能超过 20MB")
    ext = ".jpg"
    media_type = "image"
    if ct.startswith("video/"):
        ext = ".mp4"
        media_type = "video"
    elif ct == "image/png":
        ext = ".png"
    elif ct == "image/webp":
        ext = ".webp"
    folder = _static / "ad-uploads" / ctx["id"]
    folder.mkdir(parents=True, exist_ok=True)
    name = f"{uuid.uuid4().hex}{ext}"
    path = folder / name
    path.write_bytes(raw)
    url = f"{_public_base()}/static/ad-uploads/{ctx['id']}/{name}"
    return {"url": url, "mediaType": media_type}


@app.post("/api/adhub/me/shake-jump/apply")
def shake_jump_apply(req: ShakeJumpApplyRequest, ctx: Dict = Depends(current_account), db: Session = Depends(get_db)):
    try:
        row = repo.apply_shake_jump(db, ctx["id"], req.campaignId.strip(), req.message)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {"ok": True, "id": row.id, "status": row.status}


