def _parse_valid_rules(c: AdHubCampaign | None) -> list[str]:
    if not c:
        return ["watch_time"]
    raw = (c.valid_mode or "watch_time").strip()
    legacy = {
        "time_ratio": ["watch_time"],
        "click_jump": ["click_jump"],
        "browse_sec": ["browse_sec"],
        "complete_and_click": ["watch_full", "click_jump"],
        "complete_click_browse": ["watch_full", "click_jump", "browse_sec"],
    }
    if raw in legacy:
        return legacy[raw]
    tags = [t.strip() for t in raw.split(",") if t.strip()]
    return tags or ["watch_time"]


def _valid_rule_summary(c: AdHubCampaign) -> str:
    total = int(c.duration_sec)
    valid = int(c.valid_duration_sec or max(1, total - 5))
    browse = int(c.valid_browse_sec or 0)
    labels: list[str] = []
    for rule in _parse_valid_rules(c):
        if rule == "watch_time":
            labels.append(f"有效 {valid} 秒")
        elif rule == "watch_full":
            labels.append(f"看完 {total} 秒")
        elif rule == "click_jump":
            labels.append("点击跳转")
        elif rule == "browse_sec":
            labels.append(f"浏览 {browse or 3} 秒")
    return " + ".join(labels) if labels else f"有效 {valid} 秒 / 总时长 {total} 秒"


def _is_watch_valid(
    campaign: AdHubCampaign | None,
    *,
    duration_sec: int,
    clicked_jump: bool,
    browse_sec: int,
) -> bool:
    if not campaign:
        return duration_sec >= 25
    total = int(campaign.duration_sec)
    valid_min = int(campaign.valid_duration_sec or max(1, total - 5))
    browse_need = int(campaign.valid_browse_sec or 0) or 3
    checks: list[bool] = []
    for rule in _parse_valid_rules(campaign):
        if rule == "watch_time":
            checks.append(duration_sec >= valid_min)
        elif rule == "watch_full":
            checks.append(duration_sec >= total)
        elif rule == "click_jump":
            checks.append(bool(clicked_jump))
        elif rule == "browse_sec":
            checks.append(browse_sec >= browse_need)
    return all(checks) if checks else duration_sec >= valid_min


def _campaign_shake_enabled(c: AdHubCampaign) -> bool:
    if getattr(c, "shake_jump_enabled", False):
        return True
    return (c.shake_jump_mode or "off") not in ("off", "", "none")


def _shake_jump_allowed(db: Session, campaign: AdHubCampaign, publisher_id: str) -> bool:
    if not _campaign_shake_enabled(campaign):
        return False
    req = db.scalar(
        select(AdHubShakeJumpRequest).where(
            AdHubShakeJumpRequest.publisher_account_id == publisher_id,
            AdHubShakeJumpRequest.campaign_id == campaign.id,
            AdHubShakeJumpRequest.status == "approved",
            AdHubShakeJumpRequest.action == "enable",
        )
    )
    return req is not None


def apply_shake_jump(
    db: Session, publisher_id: str, campaign_id: str, *, action: str = "enable", message: str = ""
) -> AdHubShakeJumpRequest:
    campaign = db.get(AdHubCampaign, campaign_id)
    if not campaign or campaign.status != "active":
        raise ValueError("campaign_not_found")
    if not _campaign_shake_enabled(campaign):
        raise ValueError("shake_not_enabled")
    act = action if action in ("enable", "disable") else "enable"
    existing = db.scalar(
        select(AdHubShakeJumpRequest).where(
            AdHubShakeJumpRequest.publisher_account_id == publisher_id,
            AdHubShakeJumpRequest.campaign_id == campaign_id,
        )
    )
    text = message.strip() or ("申请开启摇一摇跳转" if act == "enable" else "申请关闭摇一摇跳转")
    if existing:
        existing.message = text
        existing.action = act
        existing.status = "pending"
        db.commit()
        db.refresh(existing)
        return existing
    row = AdHubShakeJumpRequest(
        publisher_account_id=publisher_id,
        campaign_id=campaign_id,
        action=act,
        message=text,
        status="pending",
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    return row


def get_shake_jump_status(db: Session, publisher_id: str, campaign_id: str) -> dict:
    campaign = db.get(AdHubCampaign, campaign_id)
    if not campaign:
        return {"shakeEnabled": False, "shakeActive": False, "status": "none"}
    enabled = _campaign_shake_enabled(campaign)
    req = db.scalar(
        select(AdHubShakeJumpRequest).where(
            AdHubShakeJumpRequest.publisher_account_id == publisher_id,
            AdHubShakeJumpRequest.campaign_id == campaign_id,
        )
    )
    active = bool(req and req.status == "approved" and req.action == "enable")
    return {
        "shakeEnabled": enabled,
        "shakeActive": active,
        "status": req.status if req else "none",
        "pendingAction": req.action if req and req.status == "pending" else "",
        "requestId": req.id if req else None,
        "canApplyEnable": enabled and (not req or req.status in ("rejected", "approved") and not active),
        "canApplyDisable": enabled and active and (not req or req.status != "pending" or req.action != "disable"),
    }


def list_shake_requests_for_advertiser(db: Session, advertiser_id: str) -> list[dict]:
    rows = db.scalars(
        select(AdHubShakeJumpRequest)
        .join(AdHubCampaign, AdHubCampaign.id == AdHubShakeJumpRequest.campaign_id)
        .where(AdHubCampaign.advertiser_account_id == advertiser_id)
        .order_by(AdHubShakeJumpRequest.created_at.desc())
        .limit(50)
    )
    out: list[dict] = []
    for r in rows:
        pub = db.get(AdHubAccount, r.publisher_account_id)
        camp = db.get(AdHubCampaign, r.campaign_id)
        out.append(
            {
                "id": r.id,
                "status": r.status,
                "action": r.action,
                "message": r.message,
                "campaignId": r.campaign_id,
                "campaignTitle": camp.title if camp else "",
                "publisherId": r.publisher_account_id,
                "publisherNickname": pub.nickname if pub else "",
                "createdAt": r.created_at.isoformat() if r.created_at else "",
            }
        )
    return out


def resolve_shake_jump_request(
    db: Session, advertiser_id: str, request_id: str, *, approve: bool
) -> AdHubShakeJumpRequest:
    row = db.get(AdHubShakeJumpRequest, request_id)
    if not row:
        raise ValueError("not_found")
    camp = db.get(AdHubCampaign, row.campaign_id)
    if not camp or camp.advertiser_account_id != advertiser_id:
        raise ValueError("forbidden")
    row.status = "approved" if approve else "rejected"
    db.commit()
    db.refresh(row)
    return row

