export function apiRequest(path, options = {}) {
  const { method = "GET", data, auth = true, timeout = 15000 } = options;
  const header = { "Content-Type": "application/json" };
  if (auth) {
    const t = getToken();
    if (t) header.Authorization = `Bearer ${t}`;
  }
  return new Promise((resolve, reject) => {
    uni.request({
      url: `${config.apiBase}${path}`,
      method,
      data,
      header,
      timeout,
      success(res) {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve(res.data);
          return;
        }
        const detail = (res.data && (res.data.detail || res.data.message)) || "请求失败";
        reject({ status: res.statusCode, detail });
      },
      fail(err) {
        const msg = err.errMsg || "网络错误";
        if (/timeout/i.test(msg)) {
          reject({ detail: "连接后端超时，请确认 8001 服务已启动（server 目录）" });
        } else if (/fail|refused/i.test(msg)) {
          reject({ detail: "无法连接后端，请先启动 server 目录下的独立 API（127.0.0.1:8001）" });
        } else {
          reject({ detail: msg });
        }
      }
    });
  });
}

