onWeixinLogin() {
  const nick = (this.nickname || "").trim();
  const phone = (this.phone || "").replace(/\D/g, "");
  if (phone && !this.validatePhone(phone)) {
    this.err = "请填写正确的11位中国大陆手机号";
    return;
  }
  this.loading = true;
  this.err = "";
  const finish = () => {
    this.loading = false;
  };
  const goHome = () => {
    uni.reLaunch({ url: "/pages/home/index" });
  };
  const loginTimeout = setTimeout(() => {
    if (!this.loading) return;
    finish();
    this.err = "登录超时，请确认后端已启动或重启微信开发者工具后重试";
  }, 20000);
  uni.login({
    provider: "weixin",
    timeout: 10000,
    success: (loginRes) => {
      const code = loginRes.code || "dev";
      apiRequest("/api/adhub/auth/weixin", {
        method: "POST",
        auth: false,
        data: {
          code,
          nickname: nick,
          avatarUrl: this.avatarUrl || ""
        }
      })
        .then((data) => {
          setToken(data.accessToken);
          clearMeCache();
          const tasks = [];
          const savedPhone = this.normalizePhoneForSave(phone);
          if (savedPhone) {
            tasks.push(
              apiRequest("/api/adhub/me/publisher", {
                method: "PUT",
                data: { contactPhone: savedPhone, contactEmail: "", websiteUrl: "", bio: "" }
              }).catch(() => null)
            );
          }
          if (nick || this.avatarUrl) {
            tasks.push(
              apiRequest("/api/adhub/me/profile", {
                method: "PUT",
                data: { nickname: nick, avatarUrl: this.avatarUrl || "" }
              }).catch(() => null)
            );
          }
          return Promise.all(tasks).then(() => {
            clearMeCache();
            goHome();
          });
        })
        .catch((e) => {
          this.err = e.detail || "登录失败";
        })
        .finally(() => {
          clearTimeout(loginTimeout);
          finish();
        });
    },
    fail: () => {
      clearTimeout(loginTimeout);
      finish();
      this.err = "微信授权失败，请重试";
    }
  });
}

