/** 有效规则原子标签，广告商可自由组合（全部满足才算有效） */
export const VALID_RULE_TAGS = [
  { value: "watch_time", label: "有效时长达标" },
  { value: "watch_full", label: "看完总时长" },
  { value: "click_jump", label: "点击跳转" },
  { value: "browse_sec", label: "浏览/操作时长" },
  { value: "play_ratio_price", label: "播放时长占比（*单价）" }
];

/** 互斥标签对：同组内不能同时选中 */
export const VALID_RULE_MUTEX_PAIRS = [
  ["watch_time", "watch_full"],
  ["watch_time", "play_ratio_price"],
  ["watch_full", "play_ratio_price"]
];

function tagLabel(value) {
  const tag = VALID_RULE_TAGS.find((t) => t.value === value);
  return tag ? tag.label : value;
}

export function getValidRulesMutexError(rules) {
  const list = rules || [];
  for (const [a, b] of VALID_RULE_MUTEX_PAIRS) {
    if (list.includes(a) && list.includes(b)) {
      return `「${tagLabel(a)}」与「${tagLabel(b)}」不能同时选择`;
    }
  }
  return "";
}

export function parseValidRules(raw) {
  if (!raw) return ["watch_time"];
  if (Array.isArray(raw)) return raw.length ? raw : ["watch_time"];
  const legacyMap = {
    time_ratio: ["watch_time"],
    click_jump: ["click_jump"],
    browse_sec: ["browse_sec"],
    complete_and_click: ["watch_full", "click_jump"],
    complete_click_browse: ["watch_full", "click_jump", "browse_sec"]
  };
  if (legacyMap[raw]) return legacyMap[raw];
  const parts = String(raw)
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return parts.length ? parts : ["watch_time"];
}

export function formatValidRule(c) {
  if (!c) return "-";
  const rules = parseValidRules(c.validRules || c.validMode);
  const total = c.durationSec || 30;
  const valid = c.validDurationSec != null ? c.validDurationSec : Math.max(1, total - 5);
  const browse = c.validBrowseSec || 0;
  const labels = rules.map((r) => {
    const tag = VALID_RULE_TAGS.find((t) => t.value === r);
    if (r === "watch_time") return `有效 ${valid} 秒`;
    if (r === "watch_full") return `看完 ${total} 秒`;
    if (r === "click_jump") return "点击跳转";
    if (r === "browse_sec") return `浏览 ${browse || 3} 秒`;
    if (r === "play_ratio_price") {
      const pps = c.pricePerSecYuan != null ? c.pricePerSecYuan : 0;
      return pps > 0 ? `按秒 ${pps} 元` : "播放占比×单价";
    }
    return tag ? tag.label : r;
  });
  return labels.join(" + ");
}

export function toggleRuleInList(list, value) {
  const set = new Set(list || []);
  if (set.has(value)) set.delete(value);
  else set.add(value);
  return Array.from(set);
}

