"""
定价与成本锚点（基于实测：6660 字全文降 AIGC ≈ ¥0.07 token 成本）。

后期可改为按吞吐量计费；当前积分仍按 1 字 ≈ 1 积分扣费。
"""
from __future__ import annotations

import os

# 实测样本：d:/测试降低ai率的论文.txt
BENCHMARK_WORDS = 6660
BENCHMARK_YUAN = 0.07

YUAN_PER_WORD = BENCHMARK_YUAN / BENCHMARK_WORDS  # ≈ 0.0000105


def ad_watch_reward_points() -> int:
    return int((os.getenv("AD_WATCH_REWARD_POINTS") or "450").strip() or "450")


def points_per_yuan() -> int:
    """充值/兑换示意：1 元可购积分（约 3× API 成本，留足毛利）。"""
    return int((os.getenv("POINTS_PER_YUAN") or "1200").strip() or "1200")


# 各会员档包含字数（周期内），API 成本约为 quota * YUAN_PER_WORD
MEMBER_PLAN_WORD_QUOTAS: dict[str, int] = {
    "d1": 6_000,
    "w7": 45_000,
    "m30": 180_000,
    "q90": 480_000,
    "h180": 880_000,
    "y365": 1_750_000,
}

MEMBER_PLAN_RETAIL_YUAN: dict[str, float] = {
    "d1": 5.99,
    "w7": 39.9,
    "m30": 149.9,
    "q90": 399.9,
    "h180": 729.9,
    "y365": 1459.9,
}


def member_plan_api_cost_yuan(plan_key: str) -> float:
    q = MEMBER_PLAN_WORD_QUOTAS.get(plan_key, 0)
    return round(q * YUAN_PER_WORD, 4)


def member_plan_gross_margin(plan_key: str) -> float:
    retail = MEMBER_PLAN_RETAIL_YUAN.get(plan_key, 0)
    if retail <= 0:
        return 0.0
    cost = member_plan_api_cost_yuan(plan_key)
    return round((retail - cost) / retail * 100, 1)

/**
 * 定价常量（与 backend/pricing.py 对齐）
 * 锚点：6660 字全文降 AIGC 实测 API 成本约 ¥0.07（token 计费）
 */
export const BENCHMARK_WORDS = 6660;
export const BENCHMARK_YUAN = 0.07;
export const YUAN_PER_WORD = BENCHMARK_YUAN / BENCHMARK_WORDS;

/** 看一次广告奖励积分（默认 450 ≈ ¥0.0047 API 成本，利于广告毛利） */
export const AD_WATCH_REWARD_POINTS = 450;

/** 示意充值：1 元 ≈ 1200 积分（全文约 5.5 元零售价 vs ¥0.07 成本） */
export const POINTS_PER_YUAN = 1200;

/** 会员周期内包含字数（用尽后按积分扣费） */
export const MEMBER_PLAN_WORD_QUOTAS: Record<string, number> = {
  d1: 6_000,
  w7: 45_000,
  m30: 180_000,
  q90: 480_000,
  h180: 880_000,
  y365: 1_750_000
};

export const MEMBER_PLAN_RETAIL_YUAN: Record<string, number> = {
  d1: 5.99,
  w7: 39.9,
  m30: 149.9,
  q90: 399.9,
  h180: 729.9,
  y365: 1459.9
};

export function memberWordsRemaining(quota: number, used: number): number {
  return Math.max(0, quota - used);
}

export function estimateApiYuan(words: number): number {
  return words * YUAN_PER_WORD;
}

/** 盈利最快路径（示意）：主推月卡 + 压低看广积分 + 会员额度用尽后积分补差 */
export const PROFIT_PLAYBOOK_SUMMARY =
  "主推 30 天月卡（毛利约 99%）；看广 450 积分/次；会员额度优先消耗，超出按积分计费。";

import React from "react";
import { MEMBER_PLAN_WORD_QUOTAS, memberWordsRemaining } from "../config/pricing";

const STORAGE_KEY = "downaigc_membership_vip";

export type VipTierSelection = {
  planKey: string;
  tagColor: string;
  planTitle: string;
  wordsQuota: number;
  wordsUsed: number;
  activatedAt: string;
};

function normalizeSelection(raw: unknown): VipTierSelection | null {
  if (!raw || typeof raw !== "object") return null;
  const j = raw as Partial<VipTierSelection>;
  if (
    typeof j.planKey !== "string" ||
    typeof j.tagColor !== "string" ||
    typeof j.planTitle !== "string"
  ) {
    return null;
  }
  const wordsQuota =
    typeof j.wordsQuota === "number"
      ? j.wordsQuota
      : MEMBER_PLAN_WORD_QUOTAS[j.planKey] ?? 0;
  const wordsUsed = typeof j.wordsUsed === "number" ? Math.max(0, j.wordsUsed) : 0;
  const activatedAt =
    typeof j.activatedAt === "string" ? j.activatedAt : new Date().toISOString();
  return {
    planKey: j.planKey,
    tagColor: j.tagColor,
    planTitle: j.planTitle,
    wordsQuota,
    wordsUsed,
    activatedAt
  };
}

function loadSelection(): VipTierSelection | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    return normalizeSelection(JSON.parse(raw));
  } catch {
    return null;
  }
}

function saveSelection(v: VipTierSelection | null) {
  try {
    if (!v) localStorage.removeItem(STORAGE_KEY);
    else localStorage.setItem(STORAGE_KEY, JSON.stringify(v));
  } catch {
    /* ignore */
  }
}

type MembershipContextValue = {
  vip: VipTierSelection | null;
  memberWordsRemaining: number;
  setVipTier: (v: Omit<VipTierSelection, "wordsUsed" | "activatedAt"> & {
    wordsQuota?: number;
  }) => void;
  consumeMemberWords: (words: number) => number;
  clearVipTier: () => void;
};

const MembershipContext = React.createContext<MembershipContextValue | null>(null);

export function MembershipProvider({ children }: { children: React.ReactNode }) {
  const [vip, setVip] = React.useState<VipTierSelection | null>(() =>
    typeof window === "undefined" ? null : loadSelection()
  );

  React.useEffect(() => {
    saveSelection(vip);
  }, [vip]);

  const setVipTier = React.useCallback(
    (v: Omit<VipTierSelection, "wordsUsed" | "activatedAt"> & { wordsQuota?: number }) => {
      const wordsQuota = v.wordsQuota ?? MEMBER_PLAN_WORD_QUOTAS[v.planKey] ?? 0;
      setVip({
        planKey: v.planKey,
        tagColor: v.tagColor,
        planTitle: v.planTitle,
        wordsQuota,
        wordsUsed: 0,
        activatedAt: new Date().toISOString()
      });
    },
    []
  );

  const consumeMemberWords = React.useCallback((words: number) => {
    if (words <= 0) return 0;
    let consumed = 0;
    setVip((prev) => {
      if (!prev) return prev;
      const remain = memberWordsRemaining(prev.wordsQuota, prev.wordsUsed);
      consumed = Math.min(words, remain);
      if (consumed <= 0) return prev;
      return { ...prev, wordsUsed: prev.wordsUsed + consumed };
    });
    return consumed;
  }, []);

  const clearVipTier = React.useCallback(() => {
    setVip(null);
  }, []);

  const remaining = vip ? memberWordsRemaining(vip.wordsQuota, vip.wordsUsed) : 0;

  const value = React.useMemo(
    () => ({
      vip,
      memberWordsRemaining: remaining,
      setVipTier,
      consumeMemberWords,
      clearVipTier
    }),
    [vip, remaining, setVipTier, consumeMemberWords, clearVipTier]
  );

  return <MembershipContext.Provider value={value}>{children}</MembershipContext.Provider>;
}

export function useMembership() {
  const ctx = React.useContext(MembershipContext);
  if (!ctx) throw new Error("useMembership must be used within MembershipProvider");
  return ctx;
}

