/** 任务扣费：优先消耗会员字数额度，不足部分按积分（1 字 ≈ 1 积分） */
export function resolveTaskCharge(
  wordCost: number,
  memberWordsRemaining: number,
  points: number
): { ok: boolean; quotaDue: number; pointsDue: number; message?: string } {
  if (wordCost <= 0) {
    return { ok: true, quotaDue: 0, pointsDue: 0 };
  }
  const quotaDue = Math.min(wordCost, Math.max(0, memberWordsRemaining));
  const pointsDue = wordCost - quotaDue;
  if (pointsDue > points) {
    return {
      ok: false,
      quotaDue,
      pointsDue,
      message: `额度与积分不足：还需 ${pointsDue.toLocaleString("zh-CN")} 积分（会员剩余 ${memberWordsRemaining.toLocaleString("zh-CN")} 字）`
    };
  }
  return { ok: true, quotaDue, pointsDue };
}

