import React from "react";
import { App, Card, Space, Typography, Row, Col, Tag, Alert } from "antd";
import { useNavigate } from "react-router-dom";
import AdCarousel, { type AdItem } from "../components/AdCarousel";
import GalaxyButton from "../components/GalaxyButton";
import { useMembership } from "../state/MembershipContext";
import {
  HOME_PROMO_COPY,
  MEMBER_PLANS,
  RECHARGE_PACKAGES,
  REGISTRATION_BONUS,
  AD_WATCH_REWARD_POINTS
} from "../config/pricing";

const y = (n: number) =>
  n.toLocaleString("zh-CN", { minimumFractionDigits: 0, maximumFractionDigits: 2 });

const hotPack = RECHARGE_PACKAGES.find((p) => p.recommended) ?? RECHARGE_PACKAGES[3];

const DashboardPage: React.FC = () => {
  const navigate = useNavigate();
  const { message } = App.useApp();
  const { setVipTier } = useMembership();

  const onActivatePlan = React.useCallback(
    async (plan: (typeof MEMBER_PLANS)[number]) => {
      const ok = await setVipTier({
        tier: plan.tier,
        tagColor: plan.tagColor,
        planTitle: plan.title
      });
      if (!ok) {
        message.error("开通失败，请登录后重试");
        return;
      }
      message.success(
        `开通成功：${plan.title}，本月已赠送 ${plan.monthlyPoints.toLocaleString("zh-CN")} 字`
      );
    },
    [message, setVipTier]
  );

  return (
    <Space direction="vertical" size={16} style={{ width: "100%" }}>
      <div className="console-stagger-item console-stagger-item--1">
        <Row gutter={[12, 12]}>
          <Col xs={24} md={12}>
            <Alert
              type="info"
              showIcon
              message="免费体验"
              description={
                <Space direction="vertical" size={4}>
                  <span>{HOME_PROMO_COPY.register}</span>
                  <span>{HOME_PROMO_COPY.daily}</span>
                </Space>
              }
            />
          </Col>
          <Col xs={24} md={12}>
            <Alert
              type="success"
              showIcon
              message="看广告免费改"
              description={`观看完整视频，${HOME_PROMO_COPY.ad}`}
              action={
                <GalaxyButton size="small" onClick={() => navigate("/console/wallet/points")}>
                  去领取
                </GalaxyButton>
              }
            />
          </Col>
        </Row>
      </div>

      <div className="console-stagger-item console-stagger-item--1b">
        <AdCarousel
          onClickAd={(ad: AdItem) => {
            if (ad.navigateTo) navigate(ad.navigateTo);
          }}
        />
