        </Typography.Title>
        <Card>
          <Space direction="vertical" size={8}>
            <Space wrap align="center">
              <Tag color="red">推荐</Tag>
              <Typography.Text strong>¥{y(hotPack.yuan)}</Typography.Text>
              <Typography.Text>
                {hotPack.points.toLocaleString("zh-CN")} 字
              </Typography.Text>
              {hotPack.hook ? (
                <Typography.Text type="secondary">（{hotPack.hook}）</Typography.Text>
