        <Row gutter={[16, 16]} className="dashboard-member-plans" align="stretch">
          {MEMBER_PLANS.map((plan) => (
            <Col key={plan.tier} xs={24} md={12}>
              <Card
                title={plan.title}
                extra={<Tag color={plan.tagColor}>{plan.tag}</Tag>}
