import React from "react";
import {
  MenuFoldOutlined,
  MenuUnfoldOutlined,
  ArrowLeftOutlined
} from "@ant-design/icons";
import { Outlet, useLocation, useNavigate } from "react-router-dom";
import AppHeader from "../components/AppHeader";
import { SideNav } from "../components/SideNav";
import { UploadDraftProvider } from "../state/UploadDraftContext";
import { useConsoleSiderHeight } from "../hooks/useConsoleSiderHeight";
import "../styles/auth.css";
import "../styles/workbench.css";

/** 段落工作台：隐藏外层「概览 / 论文优化」导航栏，仅保留顶栏与工作台自带段落侧栏 */
function isPolishWorkbenchPath(pathname: string): boolean {
  return /^\/console\/polish\/[^/]+/.test(pathname);
}

const ConsoleLayout: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const hideConsoleNav = isPolishWorkbenchPath(location.pathname);
  const [collapsed, setCollapsed] = React.useState(false);
  const [shellLayoutInstant, setShellLayoutInstant] = React.useState(false);
  const prevLayoutRef = React.useRef({ nav: hideConsoleNav, col: collapsed });

  React.useLayoutEffect(() => {
    const p = prevLayoutRef.current;
    if (p.nav === hideConsoleNav && p.col === collapsed) return;
    prevLayoutRef.current = { nav: hideConsoleNav, col: collapsed };
    setShellLayoutInstant(true);
    let innerId = 0;
    const outerId = window.requestAnimationFrame(() => {
      innerId = window.requestAnimationFrame(() => setShellLayoutInstant(false));
    });
    return () => {
      window.cancelAnimationFrame(outerId);
      if (innerId) window.cancelAnimationFrame(innerId);
      setShellLayoutInstant(false);
    };
  }, [hideConsoleNav, collapsed]);

  const handleToggleSider = React.useCallback(() => {
    setCollapsed((v) => !v);
  }, []);

  const scrollRef = useConsoleSiderHeight(!hideConsoleNav);

  return (
    <div className="console-root-layout">
      <AppHeader />
      {hideConsoleNav ? (
        <button
          type="button"
          className="workbench-back-nav-btn"
          aria-label="返回论文优化"
          title="返回论文优化"
          onClick={() => navigate("/console/polish")}
        >
          <ArrowLeftOutlined />
        </button>
      ) : null}
      <div
        ref={scrollRef}
        className={[
          "console-body",
          "console-main-scroll",
          "console-fixed-layout",
          hideConsoleNav ? "console-body--no-nav" : ""
        ]
          .filter(Boolean)
          .join(" ")}
      >
        {!hideConsoleNav ? (
          <aside
            className={[
              "console-main-sider",
              "console-main-sider--dock",
              collapsed ? "console-main-sider--collapsed" : ""
            ]
              .filter(Boolean)
              .join(" ")}
            style={{ width: collapsed ? 56 : 204 }}
          >
            <div
              className="console-sider-toggle"
              onClick={handleToggleSider}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleToggleSider();
                }
              }}
              role="button"
              tabIndex={0}
              aria-label={collapsed ? "展开侧边栏" : "收起侧边栏"}
              title={collapsed ? "展开" : "收起"}
            >
              {collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
            </div>
            <SideNav collapsed={collapsed} />
          </aside>
        ) : null}
        <main
          className={[
            "console-content-shell",
            !hideConsoleNav && collapsed ? "console-content-shell--collapsed" : "",
            hideConsoleNav ? "console-content-shell--no-console-nav" : "",
            shellLayoutInstant ? "console-content-shell--instant-margin" : ""
          ]
            .filter(Boolean)
            .join(" ")}
        >
          <UploadDraftProvider>
            <Outlet />
          </UploadDraftProvider>
        </main>
      </div>
    </div>
  );
};

export default ConsoleLayout;

