          .filter(Boolean)
          .join(" ")}
        style={{ background: "var(--bg-page)" }}
      >
        {hideConsoleNav ? (
          <button
            type="button"
            className="workbench-back-nav-btn"
            aria-label="返回论文优化"
            title="返回论文优化"
            onClick={() => navigate("/console/polish")}
          >
            <ArrowLeftOutlined />
          </button>
        ) : null}
        {!hideConsoleNav ? (
          <Sider
            className="console-main-sider"
            width={204}
            collapsible
            collapsed={collapsed}
            collapsedWidth={56}
            trigger={null}
          >
            <div
              className="console-sider-toggle"
              onClick={handleToggleSider}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleToggleSider();
                }
              }}
              role="button"
              tabIndex={0}
              aria-label={collapsed ? "展开侧边栏" : "收起侧边栏"}
              title={collapsed ? "展开" : "收起"}
            >
              {collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
            </div>
            <SideNav collapsed={collapsed} />
          </Sider>
        ) : null}
        <div
          className={[
            "console-content-shell",
            "console-fixed-layout",
            collapsed ? "console-content-shell--collapsed" : "",
            hideConsoleNav ? "console-content-shell--no-console-nav" : ""
          ]
            .filter(Boolean)
            .join(" ")}
        >
          <UploadDraftProvider>
            <Outlet />
          </UploadDraftProvider>
        </div>
      </Layout>
    </Layout>
  );
};

export default ConsoleLayout;

