import React from "react";
import { App, Card, Space, Typography, Alert } from "antd";
import { WalletOutlined, SafetyCertificateOutlined } from "@ant-design/icons";
import { useReward } from "../state/RewardContext";

const BALANCE_TIERS = [
  { yuan: 10, label: "小额" },
  { yuan: 30, label: "常用" },
  { yuan: 50, label: "推荐", recommended: true },
  { yuan: 100, label: "大额" }
] as const;

const y = (n: number) =>
  n.toLocaleString("zh-CN", { minimumFractionDigits: 0, maximumFractionDigits: 2 });

/** 顶栏金币「+」：账户余额（元）充值示意 */
const WalletBalancePage: React.FC = () => {
  const { message } = App.useApp();
  const { state, addBalanceYuan } = useReward();

  const onTopUp = React.useCallback(
    (yuan: number) => {
      addBalanceYuan(yuan);
      message.success(`已充值 ¥${y.toFixed(2)} 金币（演示）`);
    },
    [addBalanceYuan, message]
  );

  return (
    <Space direction="vertical" size={12} className="wallet-balance-page" style={{ width: "100%" }}>
      <div className="console-stagger-item console-stagger-item--1">
        <Card className="wallet-recharge-hero" styles={{ body: { padding: "12px 16px" } }}>
          <div className="wallet-recharge-hero__row">
            <div className="wallet-recharge-hero__lead">
              <Typography.Title level={5} style={{ margin: 0 }}>
                <WalletOutlined style={{ marginRight: 8, color: "#eab308" }} />
                金币充值
              </Typography.Title>
              <Typography.Text type="secondary" className="wallet-recharge-hero__meta">
                账户余额（元）· 演示环境点击即到账
              </Typography.Text>
            </div>
            <div className="wallet-recharge-hero__balance">
              <Typography.Text type="secondary" className="wallet-recharge-hero__balance-label">
                当前余额
              </Typography.Text>
              <Typography.Text strong className="wallet-recharge-hero__balance-num">
                ¥
                {state.balanceYuan.toLocaleString("zh-CN", {
                  minimumFractionDigits: 2,
                  maximumFractionDigits: 2
                })}
              </Typography.Text>
            </div>
          </div>
        </Card>
      </div>

      <div className="console-stagger-item console-stagger-item--2">
        <Typography.Title level={5} className="wallet-recharge-section-title">
          选择充值金额
        </Typography.Title>
        <div className="wallet-recharge-pack-grid wallet-recharge-pack-grid--four">
          {BALANCE_TIERS.map((tier) => (
            <button
              key={tier.yuan}
              type="button"
              className={[
                "cursor-target",
                "wallet-recharge-pack-tile",
                "console-click-panel",
                tier.recommended ? "wallet-recharge-pack-tile--hot" : ""
              ]
                .filter(Boolean)
                .join(" ")}
              onClick={() => onTopUp(tier.yuan)}
            >
              <Typography.Text strong className="wallet-recharge-pack-tile__label">
                {tier.label}
              </Typography.Text>
              <Typography.Text strong className="wallet-recharge-pack-tile__price">
                ¥{y(tier.yuan)}
              </Typography.Text>
              <Typography.Text type="secondary" className="wallet-recharge-pack-tile__hint">
                点击充值 →
              </Typography.Text>
            </button>
          ))}
        </div>
      </div>

      <div className="console-stagger-item console-stagger-item--3">
        <Alert
          type="info"
          showIcon
          icon={<SafetyCertificateOutlined />}
          className="wallet-recharge-footnote"
          message="说明"
          description="此为顶栏「¥」金币余额充值页。购买改写字数请前往「字数包充值」；免费字数请优先看激励广告。"
        />
      </div>
    </Space>
  );
};

export default WalletBalancePage;

